def girth_at_least_7(adj, n):
    # BFS from each node, detect cycles of length < 7
    for s in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        queue = [s]
        while queue:
            new_queue = []
            for u in queue:
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        if dist[v] < 3:  # only need to explore up to depth 3 for girth 7
                            new_queue.append(v)
                    elif parent[u] != v:
                        # found cycle
                        cycle_len = dist[u] + dist[v] + 1
                        if cycle_len < 7:
                            return False
            queue = new_queue
    return True

def is_3colorable(edges, n):
    # For bipartite this is trivial; check 2-colorable (bipartite)
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v); adj[v].append(u)
    color = [-1]*n
    for s in range(n):
        if color[s] == -1:
            color[s] = 0
            q = [s]
            while q:
                u = q.pop()
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1-color[u]
                        q.append(v)
                    elif color[v] == color[u]:
                        return False
    return True

