from collections import deque

def bfs_dist(adj, s, t, limit):
    if s == t: return 0
    visited = {s: 0}
    q = deque([s])
    while q:
        u = q.popleft()
        if visited[u] >= limit: break
        for v in adj[u]:
            if v not in visited:
                visited[v] = visited[u]+1
                if v == t: return visited[v]
                q.append(v)
    return float('inf')

def is_3_colorable(n, edges):
