def bfs_dist(adj, s, t, maxd):
    # returns shortest distance from s to t in current graph, or maxd+1 if > maxd
    from collections import deque
    dist = {s: 0}
    q = deque([s])
    while q:
        u = q.popleft()
        if dist[u] >= maxd:
            continue
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u]+1
                if v == t:
                    return dist[v]
                q.append(v)
    return maxd+1

