        v = order[idx]
        used = {col[u] for u in adj[v] if col[u]>=0}
        for c in range(k):
            if c not in used:
                col[v]=c
                if bt(idx+1): return True
                col[v]=-1
        return False
    if bt(0): return col
    return None

